import React, { useState, useEffect } from 'react';
import { Question, Answer } from '../types';
import { QUESTIONS } from '../constants';
import { Check, ChevronRight, X, Minus } from 'lucide-react';

interface QuizProps {
  onComplete: (answers: Answer[]) => void;
  isAccessible?: boolean;
}

const Quiz: React.FC<QuizProps> = ({ onComplete, isAccessible = false }) => {
  const [questions, setQuestions] = useState<Question[]>([]);
  const [currentIndex, setCurrentIndex] = useState(0);
  const [answers, setAnswers] = useState<Answer[]>([]);
  const [animating, setAnimating] = useState(false);
  const [direction, setDirection] = useState<'forward' | 'backward'>('forward');

  useEffect(() => {
    // Fisher-Yates shuffle algorithm to randomize questions
    const shuffled = [...QUESTIONS];
    for (let i = shuffled.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
    }
    setQuestions(shuffled);
  }, []);

  // Wait for shuffle to complete
  if (questions.length === 0) return null;

  // Ensure currentIndex is valid
  const currentQuestion = questions[currentIndex];

  const handleAnswer = (score: number) => {
    if (animating) return; // Prevent double clicks

    const newAnswer: Answer = { questionId: currentQuestion.id, score };

    const updatedAnswers = [...answers];
    updatedAnswers[currentIndex] = newAnswer;

    setAnswers(updatedAnswers);
    setDirection('forward');
    setAnimating(true);

    setTimeout(() => {
      if (currentIndex < questions.length - 1) {
        setCurrentIndex(prev => prev + 1);
        setAnimating(false);
      } else {
        // Last question - call onComplete
        try {
          onComplete(updatedAnswers);
        } catch (e) {
          console.error("Error completing quiz:", e);
          setAnimating(false);
        }
      }
    }, 200);
  };

  const handleBack = () => {
    if (currentIndex > 0 && !animating) {
      setDirection('backward');
      setAnimating(true);
      setTimeout(() => {
        setCurrentIndex(prev => prev - 1);
        setAnimating(false);
      }, 200);
    }
  };

  // Safe progress calculation
  const progress = Math.min(100, Math.round(((currentIndex + 1) / questions.length) * 100));

  return (
    <div className="max-w-3xl mx-auto w-full px-4 md:px-6 flex flex-col h-[calc(100vh-80px)] md:h-auto md:min-h-0 md:block justify-between md:justify-start" role="main" aria-label="מבחן המצפן הפוליטי">

      {/* 1. Header & Progress */}
      <div className="w-full pt-2 md:pt-0 pb-4 shrink-0" role="progressbar" aria-valuenow={progress} aria-valuemin={0} aria-valuemax={100} aria-label="התקדמות במבחן">
        <div className="flex justify-between items-center text-sm text-slate-500 dark:text-slate-400 mb-2 font-medium px-1">
          <span className="text-yellow-600 dark:text-yellow-400 font-bold text-lg md:text-base">שאלה {currentIndex + 1} <span className="text-slate-400 font-normal text-sm">/ {questions.length}</span></span>
          <span className="bg-slate-100 dark:bg-slate-800 px-2 py-0.5 rounded text-xs font-bold">{progress}%</span>
        </div>
        <div className="h-2.5 w-full bg-slate-200 dark:bg-slate-800 rounded-full overflow-hidden">
          <div 
            className="h-full bg-yellow-400 transition-all duration-300 ease-out rounded-full shadow-[0_0_10px_rgba(250,204,21,0.3)]"
            style={{ width: `${progress}%` }}
          />
        </div>
      </div>

      {/* 2. Question Card (Flexible height, centers content) */}
      <div className="flex-grow flex flex-col justify-center items-center relative py-2 md:py-12">
         <div className={`w-full transform transition-all duration-300 ease-out ${
             animating 
               ? (direction === 'forward' ? 'opacity-0 -translate-x-8' : 'opacity-0 translate-x-8') 
               : 'opacity-100 translate-x-0'
           }`}>
            {/* Question Text */}
            <h2 className="text-xl md:text-3xl font-bold text-center text-slate-900 dark:text-slate-100 leading-snug md:leading-relaxed px-2" role="heading" aria-level={2}>
                {currentQuestion.text}
            </h2>
         </div>
      </div>

      {/* 3. Answers & Navigation (Bottom anchored on mobile) */}
      <div className="shrink-0 pb-4 md:pb-8 w-full space-y-4">

        {/* Answer Grid */}
        <div className="grid grid-cols-1 md:grid-cols-5 gap-2.5 md:gap-4 w-full" role="group" aria-label="אפשרויות תשובה">

            {/* Strongly Agree (+2) */}
            <button 
                onClick={() => handleAnswer(2)}
                disabled={animating}
                aria-label="מסכים בהחלט"
                className="group relative h-14 md:h-40 rounded-xl bg-gradient-to-r md:bg-gradient-to-br from-green-500 to-green-600 text-white shadow-md hover:shadow-lg active:scale-95 transition-all flex md:flex-col items-center justify-between md:justify-center px-4 md:px-2 md:gap-3 overflow-hidden border border-transparent focus:ring-4 focus:ring-green-300 focus:outline-none"
            >
                <div className="flex items-center gap-3 md:flex-col md:gap-3">
                     <div className="bg-white/20 p-1.5 rounded-full md:bg-transparent md:p-0"><Check className="w-5 h-5 md:w-8 md:h-8 stroke-[3]" /></div>
                     <span className="font-bold text-lg md:text-lg leading-tight">מסכים בהחלט</span>
                </div>
                {/* Mobile visual decoration */}
                <div className="md:hidden w-1.5 h-1.5 bg-white rounded-full opacity-60"></div> 
            </button>

            {/* Agree (+1) */}
            <button 
                onClick={() => handleAnswer(1)}
                disabled={animating}
                aria-label="מסכים"
                className="group h-12 md:h-40 rounded-xl bg-green-50 dark:bg-green-900/20 text-green-700 dark:text-green-300 border border-green-200 dark:border-green-800 hover:bg-green-100 dark:hover:bg-green-900/30 active:scale-95 transition-all flex md:flex-col items-center justify-center gap-2 focus:ring-4 focus:ring-green-200 focus:outline-none"
            >
                <Check className="w-4 h-4 md:w-6 md:h-6" />
                <span className="font-bold text-base md:text-lg">מסכים</span>
            </button>

            {/* Neutral (0) */}
            <button 
                onClick={() => handleAnswer(0)}
                disabled={animating}
                aria-label="ניטרלי"
                className="group h-10 md:h-40 rounded-xl bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-400 border border-slate-200 dark:border-slate-700 hover:bg-slate-200 dark:hover:bg-slate-700 active:scale-95 transition-all flex md:flex-col items-center justify-center gap-2 focus:ring-4 focus:ring-slate-300 focus:outline-none"
            >
                <Minus className="w-4 h-4 md:w-6 md:h-6" />
                <span className="font-medium text-sm md:text-lg">ניטרלי</span>
            </button>

            {/* Disagree (-1) */}
            <button 
                onClick={() => handleAnswer(-1)}
                disabled={animating}
                aria-label="לא מסכים"
                className="group h-12 md:h-40 rounded-xl bg-red-50 dark:bg-red-900/20 text-red-700 dark:text-red-300 border border-red-200 dark:border-red-800 hover:bg-red-100 dark:hover:bg-red-900/30 active:scale-95 transition-all flex md:flex-col items-center justify-center gap-2 focus:ring-4 focus:ring-red-200 focus:outline-none"
            >
                <X className="w-4 h-4 md:w-6 md:h-6" />
                <span className="font-bold text-base md:text-lg">לא מסכים</span>
            </button>

            {/* Strongly Disagree (-2) */}
            <button 
                onClick={() => handleAnswer(-2)}
                disabled={animating}
                aria-label="מתנגד בהחלט"
                className="group relative h-14 md:h-40 rounded-xl bg-gradient-to-r md:bg-gradient-to-br from-red-500 to-red-600 text-white shadow-md hover:shadow-lg active:scale-95 transition-all flex md:flex-col items-center justify-between md:justify-center px-4 md:px-2 overflow-hidden border border-transparent focus:ring-4 focus:ring-red-300 focus:outline-none"
            >
                 <div className="flex items-center gap-3 md:flex-col md:gap-3">
                     <div className="bg-white/20 p-1.5 rounded-full md:bg-transparent md:p-0"><X className="w-5 h-5 md:w-8 md:h-8 stroke-[3]" /></div>
                     <span className="font-bold text-lg md:text-lg leading-tight">מתנגד בהחלט</span>
                </div>
                <div className="md:hidden w-1.5 h-1.5 bg-white rounded-full opacity-60"></div> 
            </button>
        </div>

        {/* Back Button - Minimalist text button on mobile */}
        <div className="flex justify-center md:justify-start px-1">
             <button
                onClick={handleBack}
                disabled={currentIndex === 0 || animating}
                aria-label="חזור לשאלה הקודמת"
                className={`flex items-center gap-2 py-2 px-4 rounded-lg text-sm font-medium transition-colors ${
                    currentIndex === 0 
                    ? 'text-slate-300 dark:text-slate-700 cursor-not-allowed opacity-0 md:opacity-100' 
                    : 'text-slate-500 dark:text-slate-400 hover:text-slate-800 dark:hover:text-slate-200 hover:bg-slate-100 dark:hover:bg-slate-800'
                }`}
            >
                <ChevronRight className="w-4 h-4 rotate-180" /> 
                <span>חזור לשאלה הקודמת</span>
            </button>
        </div>

      </div>
    </div>
  );
};

export default Quiz;

